<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';requireSuperAdmin();
function amount(mysqli $c,string $sql){return (float)$c->query($sql)->fetch_assoc()['total'];}
$today=amount($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid' AND DATE(paid_at)=CURDATE()");
$week=amount($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid' AND YEARWEEK(paid_at,1)=YEARWEEK(CURDATE(),1)");
$month=amount($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid' AND YEAR(paid_at)=YEAR(CURDATE()) AND MONTH(paid_at)=MONTH(CURDATE())");
$total=amount($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid'");
$byService=$conn->query("SELECT bi.service_name,COUNT(DISTINCT b.id) sales,SUM(bi.line_total) revenue FROM booking_items bi JOIN bookings b ON b.id=bi.booking_id JOIN payments p ON p.booking_id=b.id AND p.status='Paid' GROUP BY bi.service_name ORDER BY revenue DESC");
$byMethod=$conn->query("SELECT method,COUNT(*) sales,SUM(amount) revenue FROM payments WHERE status='Paid' GROUP BY method ORDER BY revenue DESC");
$exceptions=$conn->query("SELECT b.id,b.full_name,p.amount,p.status,p.reference_number FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE p.status='Refund Required' ORDER BY p.updated_at DESC");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revenue Reports | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Owner Console</div><nav><a href="super-admin-dashboard.php">Dashboard</a><a class="active" href="revenue-reports.php">Revenue</a><a href="services-management.php">Services</a><a href="technician-management.php">Technicians</a><a href="admin-management.php">Staff Admins</a><a href="system-settings.php">Settings</a><a href="audit-logs.php">Activity</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap"><div class="page-heading"><div><p class="eyebrow">SALES REPORTING</p><h1>Revenue Reports</h1><p>Includes confirmed cash payments and verified PayMongo payments. Totals are gross collections before gateway fees. Refund-required payments are excluded.</p></div></div><div class="stat-grid"><div class="stat-card money"><span>Today</span><strong>₱<?=number_format($today,2)?></strong></div><div class="stat-card money"><span>This Week</span><strong>₱<?=number_format($week,2)?></strong></div><div class="stat-card money"><span>This Month</span><strong>₱<?=number_format($month,2)?></strong></div><div class="stat-card money"><span>All Time</span><strong>₱<?=number_format($total,2)?></strong></div></div>
<div class="split-grid"><section class="panel"><h2>Revenue by Service</h2><div class="table-scroll"><table><thead><tr><th>Service</th><th>Paid Bookings</th><th>Revenue</th></tr></thead><tbody><?php while($r=$byService->fetch_assoc()):?><tr><td><?=h($r['service_name'])?></td><td><?= (int)$r['sales']?></td><td>₱<?=number_format((float)$r['revenue'],2)?></td></tr><?php endwhile;?></tbody></table></div></section><section class="panel"><h2>Revenue by Payment Method</h2><div class="table-scroll"><table><thead><tr><th>Method</th><th>Payments</th><th>Revenue</th></tr></thead><tbody><?php while($r=$byMethod->fetch_assoc()):?><tr><td><?=h($r['method'])?></td><td><?= (int)$r['sales']?></td><td>₱<?=number_format((float)$r['revenue'],2)?></td></tr><?php endwhile;?></tbody></table></div></section></div><section class="panel"><h2>Payments Requiring Refund Review</h2><p>These payments arrived after cancellation, rejection or no-show. Verify the payment reference in your PayMongo dashboard and arrange the refund there. This page does not issue refunds.</p><table><thead><tr><th>Booking</th><th>Customer</th><th>Amount</th><th>PayMongo Payment ID</th></tr></thead><tbody><?php while($r=$exceptions->fetch_assoc()):?><tr><td><?=(int)$r['id']?></td><td><?=h($r['full_name'])?></td><td>₱<?=number_format((float)$r['amount'],2)?></td><td><?=h($r['reference_number'])?></td></tr><?php endwhile;?></tbody></table></section></main></body></html>
